"use client";

/**
 * ApprovalsQueue (PHASE-007 pattern; COMPONENT_CATALOG §6.3): the pending-
 * approval worklist — rows of awaiting documents with the totals that drive
 * BR-034 decisions, inline Approve / Reject actions (SoD enforced server-
 * side; the creator's own rows render a "cannot self-approve" hint), and a
 * link into the full preview (generated by the same engine code that will
 * post — the screen only links to it, never re-implements it). Headless by
 * contract: the app supplies the rows + action handlers.
 */
import type { JSX } from "react";

import { Button } from "../components/button";
import { DocumentStatusBadge } from "../components/badge";
import { cn } from "../utils/cn";

export interface ApprovalsQueueRow {
  id: string;
  /** Document label (e.g., "JE draft — rent June"). */
  title: string;
  /** Secondary description (bilingual memo). */
  description?: string;
  /** Total BASE-currency amount (BR-034 threshold compares base). */
  totalBase: string;
  currency: string;
  /** Submitted-by display name. */
  submittedBy: string;
  submittedAt: string;
  /** True when the viewer is the creator (SoD hint — action stays server-checked). */
  isOwnSubmission: boolean;
  status: "PENDING_APPROVAL";
}

export interface ApprovalsQueueLabels {
  title: string;
  empty: string;
  approve: string;
  reject: string;
  openPreview: string;
  totalBase: string;
  submittedBy: string;
  selfApprovalHint: string;
  /** DocumentStatusBadge label for PENDING_APPROVAL (app i18n). */
  statusLabel: string;
}

export interface ApprovalsQueueProps {
  rows: readonly ApprovalsQueueRow[];
  labels: ApprovalsQueueLabels;
  onApprove?: (id: string) => void;
  onReject?: (id: string) => void;
  onOpenPreview?: (id: string) => void;
  loading?: boolean;
  disabled?: boolean;
  className?: string;
}

export function ApprovalsQueue({
  rows,
  labels,
  onApprove,
  onReject,
  onOpenPreview,
  loading = false,
  disabled = false,
  className,
}: ApprovalsQueueProps): JSX.Element {
  return (
    <section
      className={cn("rounded-lg border bg-surface", className)}
      aria-label={labels.title}
    >
      <header className="border-b px-4 py-3">
        <h2 className="text-sm font-semibold">{labels.title}</h2>
      </header>
      {loading ? (
        <div className="space-y-2 p-4" aria-busy="true">
          <div className="h-12 animate-pulse rounded bg-surface-muted" />
          <div className="h-12 animate-pulse rounded bg-surface-muted" />
        </div>
      ) : rows.length === 0 ? (
        <p className="p-8 text-center text-sm text-muted-foreground">{labels.empty}</p>
      ) : (
        <ul className="divide-y">
          {rows.map((row) => (
            <li
              key={row.id}
              className="flex flex-wrap items-center justify-between gap-3 px-4 py-3"
            >
              <div className="flex min-w-0 flex-col gap-1">
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    className="truncate text-sm font-medium hover:underline"
                    onClick={() => onOpenPreview?.(row.id)}
                  >
                    {row.title}
                  </button>
                  <DocumentStatusBadge status={row.status} label={labels.statusLabel} size="sm" />
                </div>
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
                  <span>
                    {labels.submittedBy}: {row.submittedBy} · {row.submittedAt}
                  </span>
                  <span className="font-mono tabular-nums" dir="ltr">
                    {labels.totalBase}: {row.totalBase} {row.currency}
                  </span>
                  {row.description !== undefined && row.description !== "" ? (
                    <span className="truncate">{row.description}</span>
                  ) : null}
                </div>
                {row.isOwnSubmission ? (
                  <span className="text-xs text-warning">{labels.selfApprovalHint}</span>
                ) : null}
              </div>
              <div className="flex items-center gap-2">
                <Button
                  variant="primary"
                  size="sm"
                  onClick={() => onApprove?.(row.id)}
                  disabled={disabled}
                >
                  {labels.approve}
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => onReject?.(row.id)}
                  disabled={disabled}
                >
                  {labels.reject}
                </Button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
